# ❌ OLD: Synchronous WSGI middleware blocks worker threads
# and cannot natively support WebSockets or async chunked streaming.
class TimingWSGIMiddleware:
  def __init__(self, app):
    self.app = app

  def __call__(self, environ, start_response):
    # Synchronous blocking interception:
    return self.app(environ, start_response)
